from pathlib import Path
from bs4 import BeautifulSoup
ROOT=Path(__file__).parent

def build(dist):
    p=dist/'tools.html';s=BeautifulSoup(p.read_text(encoding='utf-8'),'html.parser')
    b=s.new_tag('button',attrs={'type':'button','data-rab-mode':'revision','aria-pressed':'false'});b.string='RAB 11 Sep / model';s.select_one('.rab-mode').append(b)
    panel=BeautifulSoup('''<div id="rab-revision-panel" hidden><section id="boq-revision"><h3>RAB METTA / 11 September 2026</h3><p>Volume dari audit model dan usulan detail. Tarif dasar mengikuti Excel Bam. Pilih versi untuk membandingkan dan mengeditnya secara terpisah.</p><div class="br-controls"><label>Versi<select id="br-case"><option value="h16">Hollow 1,6 mm / studi seluruh 50×100</option><option value="h20">Hollow 2,0 mm / studi seluruh 50×100</option><option value="model">Hollow 2,3 mm / model</option><option value="source">Excel sumber</option></select></label><label>SHS 40×40<select id="br-shs"><option value="reference">Acuan: 2,0 / 2,8 mm</option><option value="s16">1,6 mm / studi</option><option value="s17">1,7 mm / studi</option><option value="s20">2,0 mm / studi</option><option value="s23">2,3 mm / studi</option></select></label><label>Tampilan satuan<select id="br-units"><option value="components">Per komponen / kg dan satuan asli</option><option value="bars">Batang 6 m / rekap per profil</option></select></label><label class="br-checkbox"><input type="checkbox" id="br-subtotals">Subtotal per kelompok</label><label class="br-checkbox"><input type="checkbox" id="br-component-subtotals">Subtotal kolom, balok, dan komponen lain</label><label class="br-checkbox"><input type="checkbox" id="br-kg-explanation">Jelaskan kg dan jumlah batang</label><label>Dasar volume<select id="br-basis"><option value="purchase">Pembelian termasuk sisa potong</option><option value="net">Bersih terpasang / estimasi</option></select></label><label class="br-checkbox"><input type="checkbox" id="br-extras">Tambahkan biaya pelengkap proyek</label></div><div class="br-totals"><div><span>UPAH / JASA</span><strong id="br-labor">—</strong></div><div><span>MATERIAL</span><strong id="br-material">—</strong></div><div><span>TOTAL</span><strong id="br-total">—</strong></div></div><div id="br-component-summary"></div><div id="br-kg-panel" hidden></div><p id="br-status" role="status">Memuat volume dan tarif…</p><details id="br-stock-detail"><summary>Verifikasi batang, kilogram dan pola potong</summary><div id="br-stock"></div></details><div class="br-actions"><button data-br-view="table" aria-pressed="true">Tabel editable</button><button data-br-view="preview" aria-pressed="false">Preview dokumen</button><button id="br-xlsx">Unduh Excel</button><button id="br-pdf">Unduh PDF</button><button id="br-json">Simpan edit JSON</button><label class="br-import">Muat edit JSON<input id="br-import" type="file" accept=".json,application/json"></label><button id="br-add">Tambah pekerjaan</button><button id="br-reset">Pulihkan versi ini</button></div><div id="br-table"><div id="br-fields" class="br-fields"></div><p id="br-unit-note"></p><div class="br-scroll"><table><thead><tr><th>No.</th><th>Uraian pekerjaan</th><th>Material</th><th>Volume</th><th>Sat.</th><th>Upah / sat.</th><th>Material / sat.</th><th>Jumlah upah</th><th>Jumlah material</th><th>Total</th><th>Dasar / aksi</th></tr></thead><tbody id="br-rows"></tbody></table></div><label class="br-note-editor">Keterangan<textarea id="br-notes"></textarea></label></div><div id="br-preview" hidden></div><p><a href="assets/r06/analisis.html" target="_blank" rel="noopener">Analisis R06: tebal, jarak kolom, biaya dan revisi gamtek</a></p><details><summary>Analisis struktur, perubahan volume dan sumber</summary><div id="br-analysis"></div></details></section></div>''','html.parser')
    s.select_one('#anggaran').append(panel)
    for name in ['boq-revision.css','boq-revision.js','boq-revision-controller.js']:
        el=s.new_tag('script',src='assets/'+name) if name.endswith('.js') else s.new_tag('link',rel='stylesheet',href='assets/'+name)
        s.body.append(el);(dist/'assets'/name).write_bytes((ROOT/name).read_bytes())
    p.write_text(str(s),encoding='utf-8')
